TYPE.TEST:

SetFunctionName("Mask4(bool, bool, bool, bool)");

for( int i=0;i<16;i++)
{
    bool x = (i & (1<<0)) ? true : false;
    bool y = (i & (1<<1)) ? true : false;
    bool z = (i & (1<<2)) ? true : false;
    bool w = (i & (1<<3)) ? true : false;
    Mask4 mask(x,y,z,w);
    Validate(
        (mask.GetX().GetBool() == x) &&
        (mask.GetY().GetBool() == y) &&
        (mask.GetZ().GetBool() == z) &&
        (mask.GetW().GetBool() == w)
    );
}


#ifdef HOST_TESTING
        SetFunctionName("Mask4(uint32_t, uint32_t, uint32_t, uint32_t)");

        uint32_t values[] = { 1, 2, 3, 4 };
        Mask4 mask(values[0], values[1], values[2], values[3]);

        Validate( 
            mask.GetX().ToUInt32() == values[0] &&
            mask.GetY().ToUInt32() == values[1] &&
            mask.GetZ().ToUInt32() == values[2] &&
            mask.GetW().ToUInt32() == values[3]
        );
#endif


SetFunctionName("Mask4(MaskScalar)");

bool boolArray[] = {true, false};
bool success = true;
for( int i=0;i<2;i++)
{
    bool testValue = boolArray[i];
    Mask4 mask(MaskScalar((bool)testValue));
    success &=
        (mask.GetX().GetBool() == testValue) &&
        (mask.GetY().GetBool() == testValue) &&
        (mask.GetZ().GetBool() == testValue) &&
        (mask.GetW().GetBool() == testValue);
}
Validate(success);


SetFunctionName("Mask4(MaskScalar, MaskScalar, MaskScalar, MaskScalar)");

for( int i=0;i<16;i++)
{
    MaskScalar x( (i & (1<<0)) ? true : false );
    MaskScalar y( (i & (1<<1)) ? true : false );
    MaskScalar z( (i & (1<<2)) ? true : false );
    MaskScalar w( (i & (1<<3)) ? true : false );
    Mask4 mask(x,y,z,w);
    Validate(
        (mask.GetX().GetBool() == x.GetBool()) &&
        (mask.GetY().GetBool() == y.GetBool()) &&
        (mask.GetZ().GetBool() == z.GetBool()) &&
        (mask.GetW().GetBool() == w.GetBool())
    );
}



SetFunctionName("Mask4(const Mask4 &)");

Mask4 maskTemp(true, false, true, false);
Mask4 mask(maskTemp);

Validate( 
     mask.GetX().GetBool() &&
    !mask.GetY().GetBool() &&
     mask.GetZ().GetBool() &&
    !mask.GetW().GetBool()
);



SetFunctionName("Mask4& operator =(const Mask4&)");

Mask4 maskTemp(true, false, true, false);
Mask4 mask;
mask = maskTemp;

Validate( 
     mask.GetX().GetBool() &&
    !mask.GetY().GetBool() &&
     mask.GetZ().GetBool() &&
    !mask.GetW().GetBool()
);



