SetFunctionName("Mask4::SetX(MaskScalar)");

Mask4 mask(false, false, false, false);

mask.SetX(MaskScalar(true));
bool result =  mask.GetX().GetBool() &&
              !mask.GetY().GetBool() &&
              !mask.GetZ().GetBool() &&
              !mask.GetW().GetBool();

mask.SetX(MaskScalar(false));
    result &= !mask.GetX().GetBool() &&
              !mask.GetY().GetBool() &&
              !mask.GetZ().GetBool() &&
              !mask.GetW().GetBool();

Validate(result);



SetFunctionName("Mask4::SetY(MaskScalar)");

Mask4 mask(false, false, false, false);

mask.SetY(MaskScalar(true));
bool result = !mask.GetX().GetBool() &&
               mask.GetY().GetBool() &&
              !mask.GetZ().GetBool() &&
              !mask.GetW().GetBool();

mask.SetY(MaskScalar(false));
    result &= !mask.GetX().GetBool() &&
              !mask.GetY().GetBool() &&
              !mask.GetZ().GetBool() &&
              !mask.GetW().GetBool();

Validate(result);



