SetFunctionName("Not(Mask4)");

Mask4 mask(true, false, true, false);
Mask4 result(Not(mask));

Validate( 
    !result.GetX().GetBool() &&
     result.GetY().GetBool() &&
    !result.GetZ().GetBool() &&
     result.GetW().GetBool()
);



SetFunctionName("And(Mask4)");

Mask4 maskA(false, false, true, true);
Mask4 maskB(false, true, false, true);
Mask4 result(And(maskA, maskB));

Validate( 
    (!result.GetX().GetBool()) &&
    (!result.GetY().GetBool()) &&
    (!result.GetZ().GetBool()) &&
    ( result.GetW().GetBool())
);



SetFunctionName("Or(Mask4)");

Mask4 maskA(false, false, true, true);
Mask4 maskB(false, true, false, true);
Mask4 result(Or(maskA, maskB));

Validate( 
    (!result.GetX().GetBool()) &&
    ( result.GetY().GetBool()) &&
    ( result.GetZ().GetBool()) &&
    ( result.GetW().GetBool())
);



SetFunctionName("Xor(Mask4)");

Mask4 maskA(false, false, true, true);
Mask4 maskB(false, true, false, true);
Mask4 result(Xor(maskA, maskB));

Validate( 
    (!result.GetX().GetBool()) &&
    ( result.GetY().GetBool()) &&
    ( result.GetZ().GetBool()) &&
    (!result.GetW().GetBool())
);



SetFunctionName("CompEqual(Mask4)");

Mask4 maskA(false, false, true, true);
Mask4 maskB(false, true, false, true);
Mask4 result(CompEqual(maskA, maskB));

Validate( 
    ( result.GetX().GetBool()) &&
    (!result.GetY().GetBool()) &&
    (!result.GetZ().GetBool()) &&
    ( result.GetW().GetBool())
);



SetFunctionName("CompNotEqual(Mask4)");

Mask4 maskA(false, false, true, true);
Mask4 maskB(false, true, false, true);
Mask4 result(CompNotEqual(maskA, maskB));

Validate( 
    (!result.GetX().GetBool()) &&
    ( result.GetY().GetBool()) &&
    ( result.GetZ().GetBool()) &&
    (!result.GetW().GetBool())
);



SetFunctionName("CompAnyTrue");

bool result = true;
for( int i=0;i<16;i++)
{
    bool x = (i & (1<<0)) ? true : false;
    bool y = (i & (1<<1)) ? true : false;
    bool z = (i & (1<<2)) ? true : false;
    bool w = (i & (1<<3)) ? true : false;
    Mask4 mask(x,y,z,w);
    bool isAnyTrue = CompAnyTrue(mask).GetBool();
    bool ref = (i!=0);
    result &= (isAnyTrue == ref);
}
Validate(result);



SetFunctionName("CompAllTrue");

bool result = true;
for( int i=0;i<16;i++)
{
    bool x = (i & (1<<0)) ? true : false;
    bool y = (i & (1<<1)) ? true : false;
    bool z = (i & (1<<2)) ? true : false;
    bool w = (i & (1<<3)) ? true : false;
    Mask4 mask(x,y,z,w);
    bool isAnyTrue = CompAllTrue(mask).GetBool();
    bool ref = (i==15);
    result &= (isAnyTrue == ref);
}
Validate(result);



SetFunctionName("SetTrue()");

Mask4 mask4;
mask4.SetTrue();

Validate( mask4.GetX().GetBool() &&
          mask4.GetY().GetBool() &&
          mask4.GetZ().GetBool() &&
          mask4.GetW().GetBool()
);



SetFunctionName("SetFalse()");

Mask4 mask4;
mask4.SetFalse();

Validate( !mask4.GetX().GetBool() &&
          !mask4.GetY().GetBool() &&
          !mask4.GetZ().GetBool() &&
          !mask4.GetW().GetBool()
);



SetFunctionName("Mask4 Select(MaskScalar mask, Mask4 a, Mask4 b)");
Mask4 v1(true, true, false, false);
Mask4 v2(true, false, true, false);

Mask4 result1 = Select( MaskScalar(true), v1, v2 );
Mask4 result2 = Select( MaskScalar(false), v1, v2 );
Validate(
    CompAllTrue(CompEqual(result1, v1)).GetBool() &&
    CompAllTrue(CompEqual(result2, v2)).GetBool()
);



SetFunctionName("Mask4 Select(Mask4 mask, Mask4 a, Mask4 b)");
Mask4 v1(true, true, false, false);
Mask4 v2(true, false, true, false);
Mask4 ref1(true, true, true, false);
Mask4 ref2(true, false, false, false);
Mask4 mask1(true, true, false, false);
Mask4 mask2(false, false, true, true);

Mask4 result1 = Select( mask1, v1, v2 );
Mask4 result2 = Select( mask2, v1, v2 );
Validate(
    CompAllTrue(CompEqual(result1, ref1)).GetBool() &&
    CompAllTrue(CompEqual(result2, ref2)).GetBool()
);



        SetFunctionName("Mask4 RotateLeft(Mask4 mask)");

#ifdef HOST_TESTING
        uint32_t values[] = { 1, 2, 3, 4 };
        Mask4 m4(values[0], values[1], values[2], values[3]);
        Mask4 mask = RotateLeft( RotateLeft(m4) );
        Validate( 
            mask.GetX().ToUInt32() == values[2] &&
            mask.GetY().ToUInt32() == values[3] &&
            mask.GetZ().ToUInt32() == values[0] &&
            mask.GetW().ToUInt32() == values[1]
        );
#else
        float_test_type values[] = { 1.0f, 2.0f, 3.0f, 4.0f };
        Mask4 m4(values[0], values[1], values[2], values[3]);
        Mask4 mask = RotateLeft( RotateLeft(m4) );
        Validate( 
            ((float_test_type)mask.GetX().mS) == values[2] &&
            ((float_test_type)mask.GetY().mS) == values[3] &&
            ((float_test_type)mask.GetZ().mS) == values[0] &&
            ((float_test_type)mask.GetW().mS) == values[1]
        );
#endif



        SetFunctionName("Mask4 RotateRight(Mask4 mask)");

#ifdef HOST_TESTING
        uint32_t values[] = { 1, 2, 3, 4 };
        Mask4 m4(values[0], values[1], values[2], values[3]);
        Mask4 mask = RotateRight( RotateRight(m4) );
        Validate( 
            mask.GetX().ToUInt32() == values[2] &&
            mask.GetY().ToUInt32() == values[3] &&
            mask.GetZ().ToUInt32() == values[0] &&
            mask.GetW().ToUInt32() == values[1]
        );
#else
        float_test_type values[] = { 1.0f, 2.0f, 3.0f, 4.0f };
        Mask4 m4(values[0], values[1], values[2], values[3]);
        Mask4 mask = RotateRight( RotateRight(m4) );
        Validate( 
            ((float_test_type)mask.GetX().mS) == values[2] &&
            ((float_test_type)mask.GetY().mS) == values[3] &&
            ((float_test_type)mask.GetZ().mS) == values[0] &&
            ((float_test_type)mask.GetW().mS) == values[1]
        );
#endif
